#include <vector>
#include <algorithm>

using namespace std;

class CyclicSortTemplate {
public:
    // Core structural loop for 1-indexed range sorting [1, n]
    void sortRange(vector<int>& nums) {
        int i = 0;
        int n = nums.size();

        while (i < n) {
            // Calculate the zero-indexed home slot for the current element
            int correctIndex = nums[i] - 1;

            // Boundary Guard: Ensure the value fits inside the array range 
            // and is not already resting at its correct home slot
            if (nums[i] > 0 && nums[i] <= n && nums[i] != nums[correctIndex]) {
                // In-place swap moves the active value to its permanent slot
                swap(nums[i], nums[correctIndex]);
                // CRITICAL: Do not increment 'i' here; evaluate the incoming element
            } else {
                // Element is either in bounds and sorted, a duplicate, or an out-of-bounds outlier
                i++;
            }
        }
    }
};

